  "stdout": "7d637be13 test(scripts): plugin manifests exist, parse and carry a valid semver version (DEFAUL-860)\n8ac7f4a77 merge: In Chat, a person creates personas, manages the org chart and its delegation tree, and assigns work to a persona (DEFAUL-845)\n    Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>\n\n scripts/lib/plugin-manifest-versions.mjs  | 53 +++++++++++++++++++++++++\n scripts/plugin-manifest-versions.test.mjs | 65 +++++++++++++++++++++++++++++++\n 2 files changed, 118 insertions(+)\n// Checks the plugin manifests carry a parsable JSON body with a valid semver `version` (DEFAUL-860). The logic takes\n// already-read entries so fixtures can exercise it; `readManifests` is the only part that touches the disk.\nimport { existsSync, readFileSync } from \"node:fs\";\nimport path from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), \"..\", \"..\");\n\nexport const MANIFEST_PATHS = [\"plugin/.claude-plugin/plugin.json\", \"plugin/.codex-plugin/plugin.json\"];\n\n// The official semver.org 2.0.0 expression.\nexport const SEMVER =\n  /^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-((?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\\.(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\\+([0-9a-zA-Z-]+(?:\\.[0-9a-zA-Z-]+)*))?$/;\n\nexport function readManifests(paths = MANIFEST_PATHS) {\n  return paths.map((rel) => {\n    const file = path.join(root, rel);\n    return { path: rel, content: existsSync(file) ? readFileSync(file, \"utf8\") : null };\n  });\n}\n\n// entries: [{ path, content }] — content is the file text, or null when the file does not exist.\n// Returns { checked, problems }; an empty corpus is itself a problem, never a pass.\nexport function checkManifestVersions(entries, isSemver = (v) => SEMVER.test(v)) {\n  const problems = [];\n  let checked = 0;\n  for (const { path: p, content } of entries) {\n    if (content === null) {\n      problems.push(`${p}: manifest file is missing`);\n      continue;\n    }\n    let parsed;\n    try {\n      parsed = JSON.parse(content);\n    } catch (e) {\n      problems.push(`${p}: not valid JSON (${e instanceof Error ? e.message : String(e)})`);\n      continue;\n    }\n    const version = parsed !== null && typeof parsed === \"object\" ? parsed.version : undefined;\n    if (typeof version !== \"string\") {\n      problems.push(`${p}: has no string \"version\"`);\n      continue;\n    }\n    if (!isSemver(version)) {\n      problems.push(`${p}: version ${JSON.stringify(version)} is not valid semver`);\n      continue;\n    }\n    checked += 1;\n  }\n  if (checked === 0 && problems.length === 0)\n    problems.push(\"checked 0 manifests: refusing to report over an empty corpus\");\n  return { checked, problems };\n}\nimport { describe, expect, it } from \"vitest\";\nimport { checkManifestVersions, MANIFEST_PATHS, readManifests } from \"./lib/plugin-manifest-versions.mjs\";\n\nconst ok = (v) => JSON.stringify({ name: \"x\", version: v });\nconst entry = (content) => [{ path: \"m.json\", content }];\n\ndescribe(\"plugin manifest versions\", () => {\n  it(\"passes on the real manifests and reports what it counted\", () => {\n    const entries = readManifests();\n    const { checked, problems } = checkManifestVersions(entries);\n    console.log(`checked ${checked} manifests`);\n    expect(problems).toEqual([]);\n    expect(checked).toBe(MANIFEST_PATHS.length);\n    expect(checked).toBe(2);\n  });\n\n  it(\"accepts valid semver including prerelease and build\", () => {\n    for (const v of [\"0.3.107\", \"1.0.0\", \"1.2.3-rc.1+build.5\"]) {\n      expect(checkManifestVersions(entry(ok(v)))).toEqual({ checked: 1, problems: [] });\n    }\n  });\n\n  it(\"fails a missing manifest file\", () => {\n    const r = checkManifestVersions(entry(null));\n    expect(r.checked).toBe(0);\n    expect(r.problems).toEqual([\"m.json: manifest file is missing\"]);\n  });\n\n  it(\"fails an unparsable manifest\", () => {\n    const r = checkManifestVersions(entry(\"{not json\"));\n    expect(r.problems[0]).toMatch(/^m\\.json: not valid JSON/);\n  });\n\n  it(\"fails a manifest with no version\", () => {\n    expect(checkManifestVersions(entry(JSON.stringify({ name: \"x\" }))).problems).toEqual([\n      'm.json: has no string \"version\"',\n    ]);\n    expect(checkManifestVersions(entry(\"null\")).problems).toHaveLength(1);\n    expect(checkManifestVersions(entry(ok(1))).problems).toHaveLength(1);\n  });\n\n  it(\"fails a non-semver version\", () => {\n    for (const v of [\"1.0\", \"v1\", \"1.0.0.0\", \"01.0.0\", \"\"]) {\n      const r = checkManifestVersions(entry(ok(v)));\n      expect(r.problems, v).toEqual([`m.json: version ${JSON.stringify(v)} is not valid semver`]);\n    }\n  });\n\n  it(\"refuses a bad fixture only because the semver check is live\", () => {\n    // Guard: with the real predicate a bad fixture is refused; a permissive one would wave it through.\n    expect(checkManifestVersions(entry(ok(\"v1\"))).problems).toHaveLength(1);\n    expect(checkManifestVersions(entry(ok(\"v1\")), () => true).problems).toEqual([]);\n  });\n\n  it(\"refuses an empty corpus instead of passing\", () => {\n    const r = checkManifestVersions([]);\n    expect(r.checked).toBe(0);\n    expect(r.problems).not.toEqual([]);\n  });\n\n  it(\"fails when any required manifest is not found\", () => {\n    const entries = readManifests().map((e, i) => (i === 0 ? { ...e, content: null } : e));\n    expect(checkManifestVersions(entries).problems).toHaveLength(1);\n  });\n});\n",
